//! Non-tautological cross-engine convergence: real yjs 13.6.30 update lineages
//! (committed fixtures, generated by `tests/fixtures/gen-fixtures.mjs`) driven
//! through the Rust durable append → reconstruct pipeline must converge on the
//! yjs-computed expectation. Fixtures come from yjs, not Rust round-tripped, so
//! a Rust regression cannot hide behind its own encoder (the spike + R08
//! pattern).
//!
//! Also proves, cross-engine: OffsetKind::Utf16 is load-bearing (a Bytes probe
//! diverges from yjs), nested-frontmatter key sorting (constraint 2), and
//! compaction convergence-neutrality against the yjs state.

use crate::common;

use common::*;
use dohc_engine_collab::{
    apply_remote_update, load_persisted, maybe_compact, record_local_update, ydoc::OffsetMode,
    CollabError, CompactOutcome, ContentKind, LocalAppend, Regime, RemoteUpdate, WriterDocCache,
    Ydoc,
};
use dohc_engine_storage::{NoFaults, TxnOutcome};
use dohc_engine_testkit::decode_hex;

const OVERLAP_U1_HEX: &str = "01010c00040109706c61696e546578740461efbfbd00";
const OVERLAP_U2_HEX: &str = "01010c00040109706c61696e546578740561f09f988000";

fn setup_parity_store(tag: &str, regime: Regime) -> (TempStore, dohc_engine_collab::DocKey) {
    let mut ts = fresh_store(tag);
    let key = test_key();
    seed_parents(&mut ts.store, &key, 1_000);
    dohc_engine_collab::ensure_marker(
        &mut ts.store,
        &key,
        ContentKind::Plaintext,
        regime,
        &NoFaults,
        1_000,
    )
    .expect("marker");
    (ts, key)
}

fn content_kind(fx: &Fixture) -> ContentKind {
    ContentKind::parse(&fx.content_kind).expect("fixture content kind")
}

/// Drive a fixture's yjs update lineage through the durable local-only pipeline
/// and return the reconstructed doc + how many updates landed.
fn ingest(fx: &Fixture) -> (TempStore, dohc_engine_collab::DocKey, i64) {
    let mut ts = fresh_store(&format!("xeng-{}", fx.seed));
    let key = test_key();
    seed_parents(&mut ts.store, &key, 1_000);
    dohc_engine_collab::ensure_marker(
        &mut ts.store,
        &key,
        content_kind(fx),
        Regime::LocalOnly,
        &NoFaults,
        1_000,
    )
    .expect("marker");
    let mut landed = 0i64;
    for (i, u) in fx.updates.iter().enumerate() {
        let bytes = decode_b64(u);
        let outcome = record_local_update(
            &mut ts.store,
            &mut ts.cache,
            &key,
            &bytes,
            LocalAppend::default(),
            &NoFaults,
            1_000 + i as i64,
            |_tx, _outcome, _update_sha| Ok(()),
        )
        .expect("record");
        if let TxnOutcome::Committed(app) = outcome {
            if !app.deduped {
                landed += 1;
            }
        }
    }
    (ts, key, landed)
}

fn assert_matches_expectation(fx: &Fixture, doc: &Ydoc) {
    match content_kind(fx) {
        ContentKind::Plaintext => {
            let expected = fx.expected["text"].as_str().expect("text");
            assert_eq!(
                doc.plaintext_string(),
                expected,
                "plaintext seed {}",
                fx.seed
            );
            // The projection of a plaintext doc IS the exact text.
            assert_eq!(
                doc.project(ContentKind::Plaintext)
                    .expect("bounded plaintext projection")
                    .content,
                expected,
                "plaintext projection seed {}",
                fx.seed
            );
        }
        ContentKind::Richdoc => {
            assert_eq!(
                doc.frontmatter_json(),
                fx.expected["frontmatter"],
                "frontmatter seed {}",
                fx.seed
            );
            let expected_paras = fx.expected["paragraphs"].as_array().expect("paras");
            let got = doc.body_paragraph_runs();
            assert_eq!(
                got.len(),
                expected_paras.len(),
                "paragraph count seed {}",
                fx.seed
            );
            for (pi, (para, exp)) in got.iter().zip(expected_paras).enumerate() {
                let exp_runs = exp["runs"].as_array().expect("runs");
                assert_eq!(
                    para.len(),
                    exp_runs.len(),
                    "run count seed {} para {}",
                    fx.seed,
                    pi
                );
                for (run, er) in para.iter().zip(exp_runs) {
                    assert_eq!(run.0, er["text"].as_str().unwrap_or(""), "run text");
                    assert_eq!(run.1, er["bold"].as_bool().unwrap_or(false), "run bold");
                    assert_eq!(run.2, er["italic"].as_bool().unwrap_or(false), "run italic");
                }
            }
            if let Some(expected_markdown) = fx.expected["markdown"].as_str() {
                assert_eq!(
                    doc.project(ContentKind::Richdoc)
                        .expect("bounded richdoc projection")
                        .content,
                    expected_markdown,
                    "richdoc markdown projection seed {}",
                    fx.seed
                );
            }
        }
        ContentKind::Scene => panic!("the legacy cross-engine corpus has no scene fixtures"),
    }
}

#[test]
fn every_fixture_converges_before_and_after_compaction() {
    let fixtures = load_all_fixtures();
    let mut plaintext = 0;
    let mut richdoc = 0;
    let mut compacted_count = 0;
    for fx in &fixtures {
        if fx.kind.is_some() {
            continue;
        }
        let (mut ts, key, _landed) = ingest(fx);
        let persisted = load_persisted(&ts.store, &key)
            .expect("load")
            .expect("marker present");
        assert_matches_expectation(fx, &persisted.doc);
        if fx.updates.len() >= 2 {
            let before = load_persisted(&ts.store, &key)
                .expect("load")
                .expect("marker")
                .doc
                .canonical_content_sha256();

            let outcome = maybe_compact(&mut ts.store, &key, 1, &NoFaults, 5_000).expect("compact");
            assert!(
                matches!(outcome, TxnOutcome::Committed(_)),
                "compact committed seed {}",
                fx.seed
            );
            // The update log is now folded away; a single snapshot remains.
            assert_eq!(
                count(&ts.store, "ydoc_updates", &key),
                0,
                "log pruned seed {}",
                fx.seed
            );
            assert_eq!(
                count(&ts.store, "ydoc_snapshots", &key),
                1,
                "one snapshot seed {}",
                fx.seed
            );

            let persisted = load_persisted(&ts.store, &key)
                .expect("load")
                .expect("marker");
            assert_eq!(
                persisted.doc.canonical_content_sha256(),
                before,
                "compaction changed converged content seed {}",
                fx.seed
            );
            assert_matches_expectation(fx, &persisted.doc);
            compacted_count += 1;
        }
        match content_kind(fx) {
            ContentKind::Plaintext => plaintext += 1,
            ContentKind::Richdoc => richdoc += 1,
            ContentKind::Scene => panic!("the legacy cross-engine corpus has no scene fixtures"),
        }
    }
    assert!(
        compacted_count >= 30,
        "compacted {compacted_count} fixtures"
    );
    // Guard against a silently-empty corpus.
    assert!(
        plaintext >= 20,
        "expected the plaintext corpus, got {plaintext}"
    );
    assert!(richdoc >= 20, "expected the richdoc corpus, got {richdoc}");
    eprintln!("cross-engine converged: {plaintext} plaintext + {richdoc} richdoc fixtures");
}

#[test]
fn richdoc_projection_matches_typescript_byte_for_byte() {
    let fixtures = load_all_fixtures();
    let mut cases = 0;
    for fx in &fixtures {
        let Some(kind) = fx.kind.as_deref() else {
            continue;
        };
        if !kind.starts_with("richdocProjection-") {
            continue;
        }
        let doc = Ydoc::wire();
        for update in &fx.updates {
            doc.apply(&decode_b64(update))
                .expect("apply TypeScript update");
        }
        let expected = fx.expected["markdown"]
            .as_str()
            .expect("TypeScript markdown expectation");
        assert_eq!(
            doc.project(ContentKind::Richdoc)
                .expect("bounded richdoc projection")
                .content,
            expected,
            "projection fixture {kind}"
        );
        cases += 1;
    }
    assert_eq!(
        cases, 30,
        "expected every live-oracle richdoc projection fixture"
    );
}

#[test]
fn offset_kind_utf16_is_load_bearing() {
    // The pinned OffsetKind probe. Seed a Utf16 doc and a Bytes doc from the same
    // real yjs base update ("😀XYZ"), then do the identical LOCAL insert of "!" at
    // UTF-16 index 4 on each. yjs measures in UTF-16, so its expectation is
    // "😀XY!Z": the Utf16 doc must match yjs; the Bytes doc (index 4 = byte 4 =
    // before "X") must diverge. This is the concrete divergence the spike found.
    let fx = load_fixture("offsetProbe");
    let base = decode_b64(fx.base_update_b64.as_ref().expect("base"));
    let expected = fx.expected["textAfterInsertAt4"]
        .as_str()
        .expect("expected");
    let insert = fx.expected["insertChar"].as_str().unwrap_or("!");
    let index = fx.expected["insertIndex"].as_u64().unwrap_or(4) as u32;

    let utf16 = Ydoc::with_mode(OffsetMode::Utf16);
    utf16.apply(&base).expect("apply base utf16");
    utf16.plaintext_insert(index, insert);

    let bytes = Ydoc::with_mode(OffsetMode::Bytes);
    bytes.apply(&base).expect("apply base bytes");
    bytes.plaintext_insert(index, insert);

    assert_eq!(
        utf16.plaintext_string(),
        expected,
        "Utf16 doc must match the yjs UTF-16 placement"
    );
    assert_ne!(
        bytes.plaintext_string(),
        expected,
        "Bytes doc must diverge from yjs — proving Utf16 is required at the boundary"
    );
    eprintln!(
        "offset probe: utf16={:?} (==yjs) bytes={:?} (diverges)",
        utf16.plaintext_string(),
        bytes.plaintext_string()
    );
}

#[test]
fn replay_parity_rejects_parked_interior_split_on_dependency_arrival() {
    let fx = load_fixture("surrogateProbe");
    let (mut ts, key) = setup_parity_store("parked-surrogate-split", Regime::Replicated);
    let dependency = decode_b64(&fx.updates[0]);
    let split = decode_b64(&fx.updates[1]);

    apply_remote_update(
        &mut ts.store,
        &mut WriterDocCache::new(),
        &key,
        &RemoteUpdate {
            origin_id: "split-peer".to_owned(),
            origin_seq: 1,
            bytes: split,
        },
        None,
        None,
        &NoFaults,
        1_001,
    )
    .expect("missing emoji dependency must park the split update");
    assert_eq!(count(&ts.store, "ydoc_updates", &key), 1);

    let error = apply_remote_update(
        &mut ts.store,
        &mut WriterDocCache::new(),
        &key,
        &RemoteUpdate {
            origin_id: "dependency-peer".to_owned(),
            origin_seq: 1,
            bytes: dependency,
        },
        None,
        None,
        &NoFaults,
        1_002,
    )
    .expect_err("dependency arrival must reject the newly integrated split");
    assert!(matches!(error, CollabError::ReplayParityViolation { .. }));
    assert_eq!(count(&ts.store, "ydoc_updates", &key), 1);
    let persisted = load_persisted(&ts.store, &key)
        .expect("load")
        .expect("marker");
    assert_eq!(persisted.doc.plaintext_string(), "");
}

// yjs-format base + delete-set candidate lineages whose delete endpoint lands
// inside a multi-unit scalar (mid-pair). yrs drops the whole scalar; yjs keeps a
// U+FFFD, so the two diverge and the gate must reject the delete.
// - delete-high: base "😀X" (client 5), delete [0,1) → removes the emoji's first
//   UTF-16 unit; endpoint clock 1 is the emoji interior.
// - delete-end:  base "A😀" (client 5), delete [0,2) → removes A + the emoji's
//   first unit; endpoint clock 2 is the emoji interior.
const DELETE_HIGH_BASE_HEX: &str = "01010500040109706c61696e5465787405f09f98805800";
const DELETE_HIGH_CANDIDATE_HEX: &str = "000105010001";
fn assert_delete_boundary_rejected(tag: &str, base_hex: &str, candidate_hex: &str) {
    let base = decode_hex(base_hex);
    let candidate = decode_hex(candidate_hex);
    let candidate_sha = dohc_engine_collab::hex_sha256(&candidate);

    // Local path.
    let (mut local, lkey) = setup_parity_store(&format!("{tag}-local"), Regime::LocalOnly);
    record_local_update(
        &mut local.store,
        &mut local.cache,
        &lkey,
        &base,
        LocalAppend::default(),
        &NoFaults,
        1_001,
        |_tx, _outcome, _update_sha| Ok(()),
    )
    .expect("local base");
    let error = record_local_update(
        &mut local.store,
        &mut local.cache,
        &lkey,
        &candidate,
        LocalAppend::default(),
        &NoFaults,
        1_002,
        |_tx, _outcome, _update_sha| Ok(()),
    )
    .expect_err("mid-pair delete must fail closed on the local path");
    assert!(
        matches!(error, CollabError::ReplayParityViolation { .. }),
        "{tag} local: {error:?}"
    );
    assert_eq!(count(&local.store, "ydoc_updates", &lkey), 1);
    assert!(
        local
            .store
            .get_binary_blob(&candidate_sha)
            .expect("blob lookup")
            .is_none(),
        "{tag} local: rejected delete must not reach the blob store"
    );

    // Remote path.
    let (mut remote, rkey) = setup_parity_store(&format!("{tag}-remote"), Regime::Replicated);
    apply_remote_update(
        &mut remote.store,
        &mut WriterDocCache::new(),
        &rkey,
        &RemoteUpdate {
            origin_id: "peer".to_owned(),
            origin_seq: 1,
            bytes: base.clone(),
        },
        None,
        None,
        &NoFaults,
        1_001,
    )
    .expect("remote base");
    let error = apply_remote_update(
        &mut remote.store,
        &mut WriterDocCache::new(),
        &rkey,
        &RemoteUpdate {
            origin_id: "peer".to_owned(),
            origin_seq: 2,
            bytes: candidate.clone(),
        },
        None,
        None,
        &NoFaults,
        1_002,
    )
    .expect_err("mid-pair delete must fail closed on the remote path");
    assert!(
        matches!(error, CollabError::ReplayParityViolation { .. }),
        "{tag} remote: {error:?}"
    );
    assert_eq!(count(&remote.store, "ydoc_updates", &rkey), 1);
    assert!(
        remote
            .store
            .get_binary_blob(&candidate_sha)
            .expect("blob lookup")
            .is_none(),
        "{tag} remote: rejected delete must not reach the blob store"
    );
}

#[test]
fn replay_parity_rejects_delete_high_surrogate_on_both_paths() {
    assert_delete_boundary_rejected(
        "delete-high",
        DELETE_HIGH_BASE_HEX,
        DELETE_HIGH_CANDIDATE_HEX,
    );
}

#[test]
fn replay_parity_rejects_mixed_parked_and_discarded_clocks_on_both_paths() {
    let origin_a = Ydoc::wire();
    let dependency = origin_a.plaintext_insert(0, "a");
    let origin_b = Ydoc::wire();
    origin_b.apply(&dependency).expect("seed dependent peer");
    let dependent = origin_b.plaintext_insert(1, "b");
    let overlap = decode_hex(OVERLAP_U2_HEX);
    let mixed = dohc_engine_collab::merge_updates(&[overlap, dependent])
        .expect("merge discarded and missing-dependency blocks");
    let mixed_sha = dohc_engine_collab::hex_sha256(&mixed);

    let (mut local, local_key) = setup_parity_store("mixed-parity-local", Regime::LocalOnly);
    let overlap_base = decode_hex(OVERLAP_U1_HEX);
    record_local_update(
        &mut local.store,
        &mut local.cache,
        &local_key,
        &overlap_base,
        LocalAppend::default(),
        &NoFaults,
        1_001,
        |_tx, _outcome, _update_sha| Ok(()),
    )
    .expect("overlap base");
    let local_error = record_local_update(
        &mut local.store,
        &mut local.cache,
        &local_key,
        &mixed,
        LocalAppend::default(),
        &NoFaults,
        1_002,
        |_tx, _outcome, _update_sha| Ok(()),
    )
    .expect_err("mixed local candidate must fail closed");
    assert!(matches!(
        local_error,
        CollabError::ReplayParityViolation { .. }
    ));
    assert_eq!(count(&local.store, "ydoc_updates", &local_key), 1);
    assert!(
        local
            .store
            .get_binary_blob(&mixed_sha)
            .expect("local blob lookup")
            .is_none(),
        "rejected mixed candidate must not reach the local blob store"
    );

    let (mut remote, remote_key) = setup_parity_store("mixed-parity-remote", Regime::Replicated);
    apply_remote_update(
        &mut remote.store,
        &mut WriterDocCache::new(),
        &remote_key,
        &RemoteUpdate {
            origin_id: "peer-overlap".to_owned(),
            origin_seq: 1,
            bytes: overlap_base,
        },
        None,
        None,
        &NoFaults,
        1_001,
    )
    .expect("remote overlap base");
    let remote_error = apply_remote_update(
        &mut remote.store,
        &mut WriterDocCache::new(),
        &remote_key,
        &RemoteUpdate {
            origin_id: "peer-mixed".to_owned(),
            origin_seq: 1,
            bytes: mixed,
        },
        None,
        None,
        &NoFaults,
        1_002,
    )
    .expect_err("mixed remote candidate must fail closed");
    assert!(matches!(
        remote_error,
        CollabError::ReplayParityViolation { .. }
    ));
    assert_eq!(count(&remote.store, "ydoc_updates", &remote_key), 1);
    assert!(
        remote
            .store
            .get_binary_blob(&mixed_sha)
            .expect("remote blob lookup")
            .is_none(),
        "rejected mixed candidate must not reach the remote blob store"
    );
}

#[test]
fn compaction_preserves_parked_updates_until_dependency_arrives() {
    let (mut ts, key) = setup_parity_store("parked-compaction", Regime::Replicated);
    let origin_a = Ydoc::wire();
    let dependency = origin_a.plaintext_insert(0, "a");
    let origin_b = Ydoc::wire();
    origin_b.apply(&dependency).expect("seed dependent peer");
    let dependent = origin_b.plaintext_insert(1, "b");

    apply_remote_update(
        &mut ts.store,
        &mut WriterDocCache::new(),
        &key,
        &RemoteUpdate {
            origin_id: "origin-b".to_owned(),
            origin_seq: 1,
            bytes: dependent,
        },
        None,
        None,
        &NoFaults,
        1_001,
    )
    .expect("missing dependency must park");
    assert_eq!(count(&ts.store, "ydoc_updates", &key), 1);

    let skipped = maybe_compact(&mut ts.store, &key, 0, &NoFaults, 1_002)
        .expect("forced compaction must inspect parked state");
    assert!(matches!(
        skipped,
        TxnOutcome::Committed(CompactOutcome::Skipped { pending: 1 })
    ));
    assert_eq!(count(&ts.store, "ydoc_updates", &key), 1);
    assert_eq!(count(&ts.store, "ydoc_snapshots", &key), 0);

    apply_remote_update(
        &mut ts.store,
        &mut WriterDocCache::new(),
        &key,
        &RemoteUpdate {
            origin_id: "origin-a".to_owned(),
            origin_seq: 1,
            bytes: dependency,
        },
        None,
        None,
        &NoFaults,
        1_003,
    )
    .expect("dependency arrival must resolve the parked update");
    assert_eq!(count(&ts.store, "ydoc_updates", &key), 2);
    let resolved = load_persisted(&ts.store, &key)
        .expect("load")
        .expect("marker");
    assert_eq!(resolved.doc.plaintext_string(), "ab");

    let compacted = maybe_compact(&mut ts.store, &key, 0, &NoFaults, 1_004)
        .expect("resolved lineage may compact");
    assert!(matches!(
        compacted,
        TxnOutcome::Committed(CompactOutcome::Compacted {
            pruned_updates: 2,
            ..
        })
    ));
    let reconstructed = load_persisted(&ts.store, &key)
        .expect("load compacted")
        .expect("marker");
    assert_eq!(reconstructed.doc.plaintext_string(), "ab");
}

// ---- inductive content-parity sweep (residual class: hostile re-encode) ----
//
// The reviewer's residual: a peer re-encodes an already-known `(client,
// clock)` with different content — without a clock shortfall (the
// candidate-clock-coverage check sees full coverage) and without an interior-
// scalar edit boundary named on the wire (the structural boundary pass sees
// nothing). No honest peer ever redefines a clock it has already used, so
// this corpus is adversarial-construction-only: for many base texts (plain
// ASCII, ASCII interleaved with multi-unit emoji, accented Latin), corrupt
// EVERY ASCII byte of the same wire update's string payload to a different
// ASCII byte and drive it back through the gate as a "candidate" claiming the
// identical (client, clock) range as the already-integrated base. Each must
// be rejected; none may panic.

// ---- cross-type redefinition (CodeRabbit gap: kind-change evades string-only
// content-parity) --------------------------------------------------------------
//
// A hostile peer can re-encode an existing STRING clock `(client, clock)` as a
// different content KIND — JSON, binary, embed, format, a Type, or deleted —
// evading a string-only units comparison (no string units to compare) while
// the scratch state vector still marks the clock covered (union-coverage
// passes). yrs dedup-by-ID vs a from-scratch yjs peer can render it
// divergently, the same threat model as the string-content residual. The gate
// tracks a per-clock structural identity for all kinds, so a kind change at a
// known live clock is rejected.

/// A length-prefixed lib0 string (1-byte length is valid for the short test
/// payloads here). Used to hand-build `read_string`/`read_json`/`read_key`
/// fields in adversarial candidate wire bytes.
fn lib0_string(s: &str) -> Vec<u8> {
    let mut out = vec![s.len() as u8];
    out.extend_from_slice(s.as_bytes());
    out
}

/// Build a candidate v1 update that re-encodes the same `(client, clock=0)` as
/// `base` (a `plaintext_insert(0, "a")` string block) but with a different
/// content kind. Reuses `base`'s exact client/clock/parent header (so the
/// candidate collides on the id) and swaps the info byte's content-ref nibble
/// (`base` has no origin/parent-sub bits set, so the low nibble IS the kind and
/// the high bits stay zero), then appends the kind's content payload and an
/// empty delete set.
fn redefine_string_clock_as(base: &[u8], content_ref: u8, content_payload: &[u8]) -> Vec<u8> {
    let marker = b"plainText";
    let marker_at = base
        .windows(marker.len())
        .position(|w| w == marker)
        .expect("plainText root marker present in base");
    let info_at = marker_at - 3; // info, parent_info(0x01), strlen(0x09), name...
    assert_eq!(
        base[info_at], 0x04,
        "base info byte is a no-origin String item"
    );
    assert_eq!(base[marker_at - 2], 0x01, "parent_info(true)");
    assert_eq!(base[marker_at - 1], 0x09, "plainText length prefix");
    let header_end = marker_at + marker.len();
    let mut out = base[..header_end].to_vec();
    out[info_at] = content_ref; // swap String -> content_ref (high bits stay 0)
    out.extend_from_slice(content_payload);
    out.push(0x00); // empty delete set
    out
}

/// The six cross-type redefinition payloads the reviewer named, each claiming
/// the base's string clock as a different content kind.
fn cross_type_redefinition_cases() -> Vec<(&'static str, u8, Vec<u8>)> {
    let deleted = vec![0x01u8]; // ContentDeleted: read_len = 1 (one tombstone clock)
    let json = {
        // ContentJSON decodes `read_len + 1` strings; read_len=0 → one JSON
        // string → one clock (colliding with the base's clock 0).
        let mut p = vec![0x00u8];
        p.extend_from_slice(&lib0_string("\"b\""));
        p
    };
    let binary = vec![0x01u8, b'b']; // ContentBinary: read_buf len=1, one byte
    let embed = lib0_string("true"); // ContentEmbed: read_json = a JSON string
    let format = {
        // ContentFormat: read_key (string) + read_json (JSON string).
        let mut p = lib0_string("b");
        p.extend_from_slice(&lib0_string("true"));
        p
    };
    let type_ref = vec![0x01u8]; // ContentType: TypeRef::Map (TYPE_REFS_MAP = 1)
    vec![
        ("deleted", 1, deleted),
        ("json", 2, json),
        ("binary", 3, binary),
        ("embed", 5, embed),
        ("format", 6, format),
        ("type", 7, type_ref),
    ]
}

#[test]
fn replay_parity_rejects_cross_type_redefinition_on_both_paths() {
    for (name, content_ref, payload) in cross_type_redefinition_cases() {
        let producer = Ydoc::wire();
        let base = producer.plaintext_insert(0, "a");
        let candidate = redefine_string_clock_as(&base, content_ref, &payload);
        let candidate_sha = dohc_engine_collab::hex_sha256(&candidate);

        // Local path.
        let (mut local, lkey) =
            setup_parity_store(&format!("xtype-{name}-local"), Regime::LocalOnly);
        record_local_update(
            &mut local.store,
            &mut local.cache,
            &lkey,
            &base,
            LocalAppend::default(),
            &NoFaults,
            1_001,
            |_tx, _outcome, _update_sha| Ok(()),
        )
        .expect("string base accepted");
        let err = record_local_update(
            &mut local.store,
            &mut local.cache,
            &lkey,
            &candidate,
            LocalAppend::default(),
            &NoFaults,
            1_002,
            |_tx, _outcome, _update_sha| Ok(()),
        )
        .expect_err(&format!("{name} local must reject the kind change"));
        assert!(
            matches!(err, CollabError::ReplayParityViolation { .. }),
            "{name} local: {err:?}"
        );
        assert_eq!(count(&local.store, "ydoc_updates", &lkey), 1);
        assert!(
            local
                .store
                .get_binary_blob(&candidate_sha)
                .expect("blob lookup")
                .is_none(),
            "{name} local: rejected redefinition must not reach the blob store"
        );

        let (mut remote, rkey) =
            setup_parity_store(&format!("xtype-{name}-remote"), Regime::Replicated);
        apply_remote_update(
            &mut remote.store,
            &mut WriterDocCache::new(),
            &rkey,
            &RemoteUpdate {
                origin_id: "peer".to_owned(),
                origin_seq: 1,
                bytes: base.clone(),
            },
            None,
            None,
            &NoFaults,
            1_001,
        )
        .expect("remote string base accepted");
        let rerr = apply_remote_update(
            &mut remote.store,
            &mut WriterDocCache::new(),
            &rkey,
            &RemoteUpdate {
                origin_id: "peer".to_owned(),
                origin_seq: 2,
                bytes: candidate.clone(),
            },
            None,
            None,
            &NoFaults,
            1_002,
        )
        .expect_err(&format!("{name} remote must reject the kind change"));
        assert!(
            matches!(rerr, CollabError::ReplayParityViolation { .. }),
            "{name} remote: {rerr:?}"
        );
        assert_eq!(count(&remote.store, "ydoc_updates", &rkey), 1);
        assert!(
            remote
                .store
                .get_binary_blob(&candidate_sha)
                .expect("blob lookup")
                .is_none(),
            "{name} remote: rejected redefinition must not reach the blob store"
        );
    }
}

#[test]
fn replay_parity_accepts_same_kind_same_payload_resend_for_each_content_kind() {
    for (name, content_ref, payload) in cross_type_redefinition_cases() {
        // `deleted` is a lone tombstone, not a meaningful "content" doc.
        // `json` (legacy ContentJSON) cannot round-trip durably in yrs 0.27.3:
        // its encoder writes `write_len(N)` + N strings but its decoder reads
        // `read_len` + N+1 strings, so a re-encoded JSON lineage is not
        // re-decodable — no honest doc ever carries it (yjs replaced it with
        // ContentAny). It stays covered by the rejection test above.
        if name == "deleted" || name == "json" {
            continue;
        }
        // A no-origin, named-root single item of this kind at (client, 0).
        let producer = Ydoc::wire();
        let string_base = producer.plaintext_insert(0, "a");
        let doc_update = redefine_string_clock_as(&string_base, content_ref, &payload);

        let (mut ts, key) = setup_parity_store(&format!("resend-{name}"), Regime::LocalOnly);
        let first = record_local_update(
            &mut ts.store,
            &mut ts.cache,
            &key,
            &doc_update,
            LocalAppend::default(),
            &NoFaults,
            1_001,
            |_tx, _outcome, _update_sha| Ok(()),
        )
        .unwrap_or_else(|e| panic!("{name} base must be accepted, got: {e:?}"));
        assert!(
            matches!(first, TxnOutcome::Committed(ref a) if !a.deduped),
            "{name} base committed"
        );
        let resend = record_local_update(
            &mut ts.store,
            &mut ts.cache,
            &key,
            &doc_update,
            LocalAppend::default(),
            &NoFaults,
            1_002,
            |_tx, _outcome, _update_sha| Ok(()),
        )
        .unwrap_or_else(|e| panic!("{name} same-kind same-payload resend must accept: {e:?}"));
        assert!(
            matches!(resend, TxnOutcome::Committed(ref a) if a.deduped),
            "{name} resend dedups (no false positive)"
        );
        assert_eq!(count(&ts.store, "ydoc_updates", &key), 1);
    }
}

#[test]
fn replay_parity_accepts_embed_resend_with_reordered_map_keys() {
    // The make-or-break false-positive boundary for the payload fingerprint: a
    // legitimate resend can re-encode an embed's map value with a different key
    // order (yrs `Any::Map` is HashMap-backed — constraint 2). The canonical
    // fingerprint sorts nested keys, so `{"a":1,"b":2}` and `{"b":2,"a":1}` are
    // the same payload and the resend must ACCEPT. (A raw-byte fingerprint would
    // false-reject this.)
    let producer = Ydoc::wire();
    let string_base = producer.plaintext_insert(0, "a");
    let base = redefine_string_clock_as(&string_base, 5, &lib0_string("{\"a\":1,\"b\":2}"));
    let reordered = redefine_string_clock_as(&string_base, 5, &lib0_string("{\"b\":2,\"a\":1}"));

    let (mut ts, key) = setup_parity_store("embed-reordered-map", Regime::LocalOnly);
    record_local_update(
        &mut ts.store,
        &mut ts.cache,
        &key,
        &base,
        LocalAppend::default(),
        &NoFaults,
        1_001,
        |_tx, _outcome, _update_sha| Ok(()),
    )
    .expect("embed base accepted");
    let outcome = record_local_update(
        &mut ts.store,
        &mut ts.cache,
        &key,
        &reordered,
        LocalAppend::default(),
        &NoFaults,
        1_002,
        |_tx, _outcome, _update_sha| Ok(()),
    )
    .expect("a same-map different-key-order embed resend must not be false-rejected");
    assert!(matches!(outcome, TxnOutcome::Committed(_)));
}

#[test]
fn replay_parity_accepts_honest_delete_gc_resend() {
    // Minimal repro: insert "abc" -> delete "b" + GC (yrs GC is on by default)
    // -> full-state resend (carries clock 1 as ContentDeleted, covered by its
    // own delete-set). The resend must accept and the durable doc converge to
    // "ac" (not be rejected and stuck at "abc").
    let (mut ts, key) = setup_parity_store("honest-delete-gc-resend", Regime::LocalOnly);
    let producer = Ydoc::wire();
    let insert = producer.plaintext_insert(0, "abc");
    record_local_update(
        &mut ts.store,
        &mut ts.cache,
        &key,
        &insert,
        LocalAppend::default(),
        &NoFaults,
        1_001,
        |_tx, _outcome, _update_sha| Ok(()),
    )
    .expect("insert abc");

    let _delete = producer.plaintext_delete(1, 1); // producer: "ac", clock 1 deleted+GC'd
    assert_eq!(producer.plaintext_string(), "ac");
    let resend = producer.encode_full_state();

    let outcome = record_local_update(
        &mut ts.store,
        &mut ts.cache,
        &key,
        &resend,
        LocalAppend::default(),
        &NoFaults,
        1_002,
        |_tx, _outcome, _update_sha| Ok(()),
    )
    .expect("an honest delete+GC full-state resend must NOT be rejected");
    assert!(matches!(outcome, TxnOutcome::Committed(_)));
    let persisted = load_persisted(&ts.store, &key)
        .expect("load")
        .expect("marker");
    assert_eq!(
        persisted.doc.plaintext_string(),
        "ac",
        "durable must converge to the deleted-content result, not stay at 'abc'"
    );
}
